mapper.select:
/* 1) 수동 등록 일정 */ SELECT s.schedule_id AS scheduleId, m.item_name AS name, TO_CHAR(s.scheduled_at, 'HH24:MI') AS time, CASE WHEN s.routine_id IS NOT NULL THEN 'supplement' WHEN s.cabinet_id IS NOT NULL THEN 'regular' ELSE 'regular' END AS type, s.taken_at AS takenAt, 1 AS alarmEnabled FROM schedules s JOIN medications m ON s.medication_id = m.medication_id WHERE s.user_id = #{userId} AND TRUNC(s.scheduled_at) = TO_DATE(#{date}, 'YYYY-MM-DD')
UNION ALL
/* 2) 처방전 실시간 연동: medications 조인으로 진짜 약품명 추출 */ SELECT (p.prescription_id * 1000 + pi.item_id) AS scheduleId, m.item_name AS name, '08:30' AS time, 'prescription' AS type, NULL AS takenAt, 1 AS alarmEnabled FROM prescriptions p JOIN prescription_items pi ON p.prescription_id = pi.prescription_id JOIN medications m ON pi.medication_id = m.medication_id WHERE p.user_id = #{userId}
AND TO_DATE(#{date}, 'YYYY-MM-DD') >= TRUNC(p.dispensed_date) AND TO_DATE(#{date}, 'YYYY-MM-DD') < TRUNC(p.dispensed_date) + p.total_days
ORDER BY time ASC

WITH ALL_CALENDAR AS ( /* 수동 등록 일정 */ SELECT TO_CHAR(s.scheduled_at, 'YYYY-MM-DD') AS scheduleDate, 0 AS hasPrescription, CASE WHEN s.routine_id IS NULL THEN 1 ELSE 0 END AS hasRegular, CASE WHEN s.routine_id IS NOT NULL THEN 1 ELSE 0 END AS hasSupplement FROM schedules s WHERE s.user_id = #{userId} AND TO_CHAR(s.scheduled_at, 'YYYY-MM') = #{yearMonth}
UNION ALL
/* 처방전 유효 기간 내 날짜 */ SELECT TO_CHAR(TRUNC(p.dispensed_date) + LEVEL - 1, 'YYYY-MM-DD') AS scheduleDate, 1 AS hasPrescription, 0 AS hasRegular, 0 AS hasSupplement FROM prescriptions p WHERE p.user_id = #{userId} AND TO_CHAR(TRUNC(p.dispensed_date) + LEVEL - 1, 'YYYY-MM') = #{yearMonth}
CONNECT BY LEVEL <= p.total_days AND PRIOR p.prescription_id = p.prescription_id AND PRIOR SYS_GUID() IS NOT NULL
) SELECT scheduleDate AS "scheduleDate", MAX(hasPrescription) AS "hasPrescription", MAX(hasRegular) AS "hasRegular", MAX(hasSupplement) AS "hasSupplement" FROM ALL_CALENDAR GROUP BY scheduleDate

mapper.update:
UPDATE schedules
   SET taken_at = CASE WHEN #{isTaken} = 1 THEN SYSDATE ELSE NULL END
 WHERE schedule_id = #{scheduleId}

UPDATE schedules
   SET scheduled_at = TO_DATE(TO_CHAR(scheduled_at, 'YYYY-MM-DD') || ' ' || #{newTime}, 'YYYY-MM-DD HH24:MI')
 WHERE schedule_id = #{scheduleId}
